import express from "express";

const MODULE_VERSION = "2026-08-30-amazon-y3-main-image-asset-v1.1.0";
const ROUTE = "/assets/y3-main.jpg";
const originalListen = express.application.listen;

const IMAGE_BASE64 = "";
const IMAGE_BYTES = Buffer.from(IMAGE_BASE64, "base64");

express.application.listen = function amazonY3MainImageAssetListen(...args) {
  const alreadyRegistered = Boolean(this?._router?.stack?.some(layer => layer?.route?.path === ROUTE));
  if (!alreadyRegistered) {
    this.get(ROUTE, (req, res) => {
      res.set("Cache-Control", "public, max-age=60");
      res.set("X-Y3-Image-Version", MODULE_VERSION);
      res.type("image/jpeg");
      return res.status(200).send(IMAGE_BYTES);
    });
  }
  return originalListen.apply(this, args);
};
